#!/bin/bash

# This test file is executed against an auto-generated devcontainer.json that
# includes the 'personal-features' Feature alone (it has no options - this
# Feature is the owner's personal, opinionated setup, so everything below is
# always installed).
#
# Installing Claude Code requires npm, so the autogenerated job in
# .github/workflows/test.yaml runs this against Node-enabled base images
# rather than bare debian/ubuntu - see src/personal-features/NOTES.md for why
# Node isn't bundled into this Feature itself.
#
# This test can be run with the following command:
#
#    devcontainer features test \
#               --features personal-features \
#               --remote-user root \
#               --skip-scenarios \
#               --base-image mcr.microsoft.com/devcontainers/javascript-node:latest \
#               /path/to/this/repo

set -e

# shellcheck source=/dev/null  # dev-container-features-test-lib is injected by the test harness at runtime; not resolvable statically. check()/reportResults() come from it.
source dev-container-features-test-lib

check "claude wrapper is on PATH and executable" bash -c "test -x \"\$(command -v claude)\""
check "claude reports a version" claude --version

# #741: install.sh pins @anthropic-ai/claude-code to an exact version
# (CLAUDE_CODE_VERSION) and the feature sets DISABLE_AUTOUPDATER=1, so the
# version installed at build time is the version the container keeps. Assert the
# pin actually took - an unpinned install, or an autoupdater that slipped past
# the env var, both show up here as a mismatch. Bump this string whenever
# CLAUDE_CODE_VERSION moves.
check "claude is pinned to 2.1.268" bash -c \
  "claude --version | grep -qF '2.1.268'"

# The wrapper injects --ide ONLY for a bare interactive session (no args + TTY)
# and passes everything else straight through, so a new Claude Code subcommand
# can never be mangled into `claude --ide <subcommand>` (see NOTES.md). Assert
# the guard (`$# -eq 0` + `[ -t 0 ]`) and the verbatim passthrough exec are
# present, and that no stale subcommand allowlist (`case "$1" in`) survives.
check "wrapper injects --ide only for a bare interactive session" bash -c \
  "grep -qF -- '\$# -eq 0' \"\$(command -v claude)\" && grep -qF -- '[ -t 0 ]' \"\$(command -v claude)\" && grep -qF -- 'exec \"\$REAL\" --ide' \"\$(command -v claude)\""
check "wrapper passes everything else (subcommands, flags, prompts) through untouched" bash -c \
  "grep -qF -- 'exec \"\$REAL\" \"\$@\"' \"\$(command -v claude)\""
check "wrapper has no hardcoded subcommand allowlist" bash -c \
  "! grep -qF 'case \"\$1\" in' \"\$(command -v claude)\""

check "claude config dir exists" bash -c "test -d /usr/local/share/claude-home"
check "gh config dir exists" bash -c "test -d /usr/local/share/gh-cli-config"
check "odoo-sdk config dir exists" bash -c "test -d /usr/local/share/odoo-sdk-config"
check "CLAUDE_CONFIG_DIR points at the bind mount" bash -c "[ \"\$CLAUDE_CONFIG_DIR\" = '/usr/local/share/claude-home' ]"
check "GH_CONFIG_DIR points at the bind mount" bash -c "[ \"\$GH_CONFIG_DIR\" = '/usr/local/share/gh-cli-config' ]"

# #239: the SDK config env var is the uppercase ODOO_SDK_CONFIG pointing at the
# mount DIRECTORY (the SDK probes it for config.toml/config.ini). The old
# lowercase odoo_sdk_CONFIG (which pointed at a specific config.ini file) must be
# gone - a case-sensitive stale name would leave the SDK reading nothing.
check "ODOO_SDK_CONFIG points at the bind mount dir" bash -c \
  "[ \"\$ODOO_SDK_CONFIG\" = '/usr/local/share/odoo-sdk-config' ]"
check "legacy lowercase odoo_sdk_CONFIG is not set" bash -c "[ -z \"\$odoo_sdk_CONFIG\" ]"

# NOTE: no check here that the odoo-sdk MCP server is registered. install.sh
# registers it at BUILD time into CLAUDE_CONFIG_DIR=/usr/local/share/claude-home,
# but at RUNTIME that directory is shadowed by the feature's bind mount of the
# host's ~/.claude (empty on CI runners and fresh hosts), so `claude mcp get
# odoo-sdk` reports the server as missing whenever the mount is active - i.e.
# always in real use. Asserting it here would test something the feature cannot
# deliver; a runtime-registration mechanism (e.g. a feature-contributed
# postCreateCommand) is a separate product decision.

# Regression guard for #120: the odoo-tui curses TUI console script is symlinked
# onto PATH whenever the SDK is installed (i.e. whenever odoo-mcp is present).
# Gated on the odoo-mcp binary so it no-ops when no SDK wheel was bundled (e.g.
# a plain `devcontainer features test` without CI's wheel-bundling step; since
# #674 the base image's Python version is irrelevant - the tool env carries its
# own uv-managed interpreter). PATH checks are unaffected by the bind mounts
# above.
check "odoo-tui console script is on PATH when the SDK is installed" bash -c \
  "! test -x /usr/local/bin/odoo-mcp || test -x \"\$(command -v odoo-tui)\""

# Regression guard for #674's first cut: the venv shebang points at
# $_SDK_ENV/bin/python, itself a symlink to the uv-managed CPython. uv's default
# install dir is under the installing user's HOME - root's, mode 0700 - so every
# console script exec'd as a non-root remoteUser died with
# `bad interpreter: Permission denied`. Only the images with a non-root
# remoteUser (javascript-node ships `node`) reproduced it; the odoo/root matrix
# legs stayed green. Assert the interpreter actually RUNS as whoever this test
# is, not merely that the symlink resolves - `test -x` follows the link and
# would pass on an unreadable target's mode bits.
check "the uv-managed interpreter is runnable by a non-root remoteUser" bash -c \
  "! test -x /usr/local/bin/odoo-mcp || /usr/local/share/uv/tools/odoo-sdk/bin/python -c 'import sys; print(sys.executable)'"

# #369: the central tracker DB is HOST-provisioned and bind-mounted; the
# container consumes it and never creates one. This reverses the #115 stance
# (which wrongly concluded the state dir couldn't be mounted): updateRemoteUserUID
# remaps the user at container-create so bind mounts line up - the six credential
# mounts already prove it - and install.sh must NOT pre-create the tracker target
# (provision=host in persisted-paths.tsv), or a broken mount would masquerade as a
# working one behind an empty container-local DB. CI runs `sh ./setup.sh` on the
# runner before this test, so the host dir + schema exist and the mount delivers
# them at $ODOO_TASK_TRACKER_DIR.
#
# #552/#533: both checks used to gate on `! command -v odoo-sdk || {...}`, but
# install.sh symlinks only odoo-mcp/odoo-tui onto PATH - `odoo-sdk` never
# resolves, so the guard short-circuited to a vacuous exit 0 and NEITHER body had
# ever executed. They now gate on the real "is the SDK installed at all"
# condition the :69 check uses (/usr/local/bin/odoo-mcp, absent only when no
# wheel was bundled - the base image's Python no longer matters, #674) and
# invoke the CLI at its uv-managed venv path, the same one the #411 e2e check
# below resolves.
_SDK_CLI=/usr/local/share/uv/tools/odoo-sdk/bin/odoo-sdk

# POSITIVE: with the mount live, `odoo-sdk log-event` writes into the central DB.
# A missing/unmounted DB would make log-event exit non-zero (the hard error
# below), so a successful write that lands tracker.db at the mounted path is the
# rebuild-surviving derivation reachability of acceptance #3. No
# --attach-active-run, so the row stays untargeted and accrues no billable time
# against a real run if this ever runs against a host-provisioned DB.
check "odoo-sdk log-event writes to the host-provisioned central tracker DB" bash -c \
  "! test -x /usr/local/bin/odoo-mcp || { $_SDK_CLI log-event --source claude:SessionStart --subject ci-positive && test -f \"\$ODOO_TASK_TRACKER_DIR/tracker.db\"; }"

# NEGATIVE: point the state root at an empty dir with no host-provisioned DB; the
# SDK must refuse to self-create one and fail with the single actionable error
# naming the expected path (acceptance #4), never exiting 0 silently. Chained
# with && (not ;) so the non-zero-exit half is actually asserted: `check` runs
# the body in a child shell that does not inherit this file's `set -e`.
check "odoo-sdk refuses to self-create a missing central tracker DB" bash -c \
  "! test -x /usr/local/bin/odoo-mcp || { d=\"\$(mktemp -d)\"; ! ODOO_TASK_TRACKER_DIR=\"\$d\" $_SDK_CLI log-event --source claude:SessionStart --subject ci-negative 2>\"\$d/err\" && grep -q \"\$d/tracker.db\" \"\$d/err\" && ! test -f \"\$d/tracker.db\"; }"

# productivity/navigation CLIs
check "ripgrep is installed" rg --version
check "fd is installed" fd --version
check "fzf is installed" fzf --version
check "bat is installed" bat --version
check "jq is installed" jq --version
check "yq is installed" yq --version
check "eza is installed" eza --version
check "zoxide is installed" zoxide --version
check "tldr is installed" tldr --version
check "qsv is installed" qsv --version

# git QoL tools
check "delta is installed" bash -c "test -x \"\$(command -v delta)\" && delta --version"
check "lazygit is installed" bash -c "test -x \"\$(command -v lazygit)\" && lazygit --version"

# secret scanning
check "gitleaks is installed" gitleaks version

# GitHub CLI (#597: hard dependsOn on ghcr.io/devcontainers/features/github-cli -
# the feature ships gh-dependent tooling like create-pr and the mounted
# GH_CONFIG_DIR, so a built container must always have gh on PATH. Presence
# check only: CI has no token, so no auth assertions here.)
check "gh is installed" gh --version

# create-pr (config-driven gh pr create wrapper)
check "create-pr is installed and executable" bash -c "test -x /usr/local/bin/create-pr"
check "create-pr passes shell syntax check" bash -c "sh -n /usr/local/bin/create-pr"
check "PR_AUTOMATION_CONFIG_DIR points at the bind mount" bash -c \
  "[ \"\$PR_AUTOMATION_CONFIG_DIR\" = '/usr/local/share/pr-automation' ]"
check "pr-automation config dir exists" bash -c "test -d /usr/local/share/pr-automation"

# CodeRabbit CLI (best-effort install; check the binary is present + on PATH)
check "coderabbit is installed" bash -c "test -x \"\$(command -v coderabbit)\""
check "coderabbit config dir exists" bash -c "test -d /usr/local/share/coderabbit-config"
check "CODERABBIT_CONFIG_DIR points at the bind mount" bash -c "[ \"\$CODERABBIT_CONFIG_DIR\" = '/usr/local/share/coderabbit-config' ]"
# #661: the CLI hardcodes join(homedir(), ".coderabbit") for its auth/state
# (auth.json, machine-id) and ignores CODERABBIT_CONFIG_DIR entirely, so the
# persisted target must be the container user's literal home path.
check "coderabbit CLI home state dir exists (#661)" bash -c "test -d /home/vscode/.coderabbit"

# global git hooks
check "global core.hooksPath is configured" bash -c "[ \"\$(git config --system --get core.hooksPath)\" = '/usr/local/share/git-hooks' ]"
check "global commit-msg hook is executable" bash -c "test -x /usr/local/share/git-hooks/commit-msg"
check "global pre-commit hook is executable" bash -c "test -x /usr/local/share/git-hooks/pre-commit"

# delta wired in as git's pager machine-wide (--system scope)
check "git core.pager is set to delta" bash -c \
  "[ \"\$(git config --system --get core.pager)\" = 'delta' ]"
check "git interactive.diffFilter uses delta" bash -c \
  "[ \"\$(git config --system --get interactive.diffFilter)\" = 'delta --color-only' ]"

# --- machine-wide git excludes (#643) ----------------------------------------
# mempalace `init` writes entities.json / mempalace.yaml / .mempalace/ into
# whatever project it is pointed at and offers no way to redirect them, so they
# are ignored machine-wide at --system scope instead of via a per-repo
# .gitignore append. Assert the wiring AND the behaviour it exists for.
check "git core.excludesfile points at the shipped excludes file" bash -c \
  "[ \"\$(git config --system --get core.excludesfile)\" = '/usr/local/share/git-excludes/gitignore' ]"
check "the shipped global excludes file exists" bash -c \
  "test -f /usr/local/share/git-excludes/gitignore"
for _pattern in mempalace.yaml entities.json .mempalace/ chroma.sqlite3 \
                knowledge_graph.sqlite3 hallways.json known_entities.json \
                hook_state/ wal/ locks/; do
  check "global excludes file ignores $_pattern" bash -c \
    "grep -qxF '$_pattern' /usr/local/share/git-excludes/gitignore"
done

# The assertion that actually matters: a real repo, real files, empty status.
check "mempalace init artifacts are invisible to git status in a fresh repo" bash -c \
  "d=\"\$(mktemp -d)\"; cd \"\$d\" && git init -q . && touch mempalace.yaml entities.json && mkdir -p .mempalace && touch .mempalace/config.json && [ -z \"\$(git status --porcelain)\" ]"
# Negative control - without it the check above would also pass if git status
# were broken or the repo were somehow not a repo at all.
check "an unrelated untracked file is still reported by git status" bash -c \
  "d=\"\$(mktemp -d)\"; cd \"\$d\" && git init -q . && touch some-real-file.txt && [ -n \"\$(git status --porcelain)\" ]"
# Tradeoff-1 escape hatch: a repo that genuinely tracks one of these generic
# filenames gets it back with a negation in its own .gitignore.
check "a repo can negate a global exclude in its own .gitignore" bash -c \
  "d=\"\$(mktemp -d)\"; cd \"\$d\" && git init -q . && printf '!entities.json\n' > .gitignore && touch entities.json && git status --porcelain | grep -q 'entities.json'"

# shell enhancements
check "starship is installed" starship --version
check "shell history dir exists" bash -c "test -d /usr/local/share/shell-history"
# shellcheck disable=SC2088  # literal ~ in a human-readable test description, not a path to expand
check "~/.bash_history is linked to the bind-mounted history file" bash -c \
  "[ \"\$(readlink -f \"\$HOME/.bash_history\")\" = '/usr/local/share/shell-history/bash_history' ]"

# Regression guard for #198: shell history is bind-mounted as a *directory*, not
# as a single file. Docker Desktop materialises a missing single-file mount
# source as a directory on the host, which then fails the mount - so the mount
# target must be the directory, with the history file living inside it.
check "shell history mount target is a directory, not a file" bash -c \
  "test -d /usr/local/share/shell-history && ! test -L /usr/local/share/shell-history"

# Regression guard for #198: on a first run against an empty host directory the
# history file doesn't exist yet, so the ~/.bash_history symlink is dangling.
# That has to self-heal - bash opens HISTFILE with O_CREAT, which follows the
# symlink and creates the target. Simulate it by removing the file first.
check "a dangling history symlink self-heals on first write" bash -c \
  "rm -f /usr/local/share/shell-history/bash_history \
   && printf 'echo 198\n' >> \"\$HOME/.bash_history\" \
   && test -f /usr/local/share/shell-history/bash_history"

# Regression guard for #198: HISTFILE is set system-wide (so history persists
# for every user, not just the one whose home was symlinked), and histappend is
# a correctness fix - without it bash truncates HISTFILE on exit and rewrites it
# from memory, so one shell exiting would wipe a concurrent container's history.
check "HISTFILE points at the bind-mounted history file" bash -c \
  "grep -q '^export HISTFILE=/usr/local/share/shell-history/bash_history$' /etc/bash.bashrc"
check "histappend is enabled so concurrent shells don't truncate history" bash -c \
  "grep -q '^shopt -s histappend$' /etc/bash.bashrc"

# Regression guard for #198: assert the *runtime* value, not just the file. Both
# `starship init` and `zoxide init` overwrite PROMPT_COMMAND, so if the flush is
# set before them in the snippet it is silently dropped and history is only
# written on a clean exit (losing it whenever the container is killed).
# /etc/bash.bashrc is guarded by `[ -z "$PS1" ] && return`, so this has to run an
# interactive shell to see the assembled value at all.
check "history -a survives starship/zoxide clobbering PROMPT_COMMAND" bash -ic \
  "[[ \$PROMPT_COMMAND == *'history -a'* ]]"

check "starship.toml was placed in global share" bash -c "test -f /usr/local/share/starship.toml"
check "shell snippet was appended to global bashrc" bash -c "grep -q 'personal-features' /etc/bash.bashrc"

# Claude consulting skills are NOT shipped loose any more (#738). They ride in
# the odoo-dev plugin that sync-claude-mcp installs from this repo's own
# marketplace (#723), so install.sh stages nothing under /usr/local/share/
# personal-features/skills and installs no sync-claude-skills publisher - a
# loose copy would load as a personal skill alongside its plugin twin and
# compete for the same triggers. Assert both are gone, or a rebuild would
# quietly start seeding them again.
check "sync-claude-skills is no longer installed" bash -c \
  "! test -e /usr/local/bin/sync-claude-skills"
check "the skills staging dir is no longer created" bash -c \
  "! test -e /usr/local/share/personal-features/skills"

# --- sync-claude-mcp: odoo-dev plugin + stale loose skill cleanup (#738) ------
# sync-claude-mcp runs from postCreateCommand, which `devcontainer features
# test` never executes, so drive it by hand here - against a THROWAWAY
# CLAUDE_CONFIG_DIR and a STUB `claude` that records its argv, never the real
# config dir and never a real marketplace/network call. Same stub pattern as the
# mempalace-init-workspace checks further down.
MCP_TEST_ROOT="$(mktemp -d)"
MCP_STUB_BIN="$MCP_TEST_ROOT/bin"
MCP_CONFIG="$MCP_TEST_ROOT/claude-home"
mkdir -p "$MCP_STUB_BIN" \
  "$MCP_CONFIG/skills/odoo-quote" \
  "$MCP_CONFIG/skills/fibonacci-estimate" \
  "$MCP_CONFIG/skills/client-status-report" \
  "$MCP_CONFIG/skills/my-own-skill" \
  "$MCP_CONFIG/skills/odoo-code-review"
# Three of the six names the retired sync used to seed, a DECOY user-authored
# skill that must survive, and a named dir with NO SKILL.md - which is not a
# skill by check-stray-skills.sh's definition and so must survive too.
printf 'stale loose odoo-quote\n'               > "$MCP_CONFIG/skills/odoo-quote/SKILL.md"
printf 'stale loose fibonacci-estimate\n'       > "$MCP_CONFIG/skills/fibonacci-estimate/SKILL.md"
printf 'stale loose client-status-report\n'     > "$MCP_CONFIG/skills/client-status-report/SKILL.md"
printf 'my hand-written skill - do not touch\n' > "$MCP_CONFIG/skills/my-own-skill/SKILL.md"
printf 'loose notes, no SKILL.md\n'             > "$MCP_CONFIG/skills/odoo-code-review/notes.txt"

# Succeeds at everything and records what it was asked to do. Printing NOTHING
# for `plugin list` is what drives the install branch: the idempotency guard
# greps that output for an already-installed odoo-dev.
cat > "$MCP_STUB_BIN/claude" <<'STUB'
#!/bin/sh
printf '%s\n' "$*" >> "$0.calls"
exit 0
STUB
chmod +x "$MCP_STUB_BIN/claude"

check "sync-claude-mcp runs clean against a stub claude" bash -c \
  "CLAUDE_CONFIG_DIR=\"$MCP_CONFIG\" PATH=\"$MCP_STUB_BIN:\$PATH\" /usr/local/bin/sync-claude-mcp"

# The plugin install is pinned to this repo's marketplace by the
# plugin@marketplace form, so a same-named plugin elsewhere cannot satisfy it.
check "sync-claude-mcp installs odoo-dev pinned to the devcontainer-features marketplace" bash -c \
  "grep -qF 'plugin install --scope user odoo-dev@devcontainer-features' \"$MCP_STUB_BIN/claude.calls\""

# The point of #738: copies written into the bind-mounted ~/.claude by
# pre-migration containers outlive the image that wrote them and shadow their
# odoo-dev twins. With the plugin in place they are deleted.
check "sync-claude-mcp removes the stale loose skill copies the plugin now ships" bash -c \
  "! test -e \"$MCP_CONFIG/skills/odoo-quote\" && ! test -e \"$MCP_CONFIG/skills/fibonacci-estimate\" && ! test -e \"$MCP_CONFIG/skills/client-status-report\""

# ...and nothing else. The name list is literal and the SKILL.md test is the
# same "stray" definition check-stray-skills.sh uses.
check "sync-claude-mcp leaves a user-authored skill untouched" bash -c \
  "grep -q 'do not touch' \"$MCP_CONFIG/skills/my-own-skill/SKILL.md\""
check "sync-claude-mcp leaves a named dir carrying no SKILL.md alone" bash -c \
  "test -f \"$MCP_CONFIG/skills/odoo-code-review/notes.txt\""

# A container that could not reach the marketplace must keep whatever skills it
# has: deleting the loose copy there would leave the machine with neither copy.
# The run still exits 0 - this whole script is best-effort and must never fail
# container create.
MCP_FAIL_BIN="$MCP_TEST_ROOT/bin-offline"
MCP_FAIL_CONFIG="$MCP_TEST_ROOT/claude-home-offline"
mkdir -p "$MCP_FAIL_BIN" "$MCP_FAIL_CONFIG/skills/odoo-quote"
printf 'stale loose odoo-quote\n' > "$MCP_FAIL_CONFIG/skills/odoo-quote/SKILL.md"
cat > "$MCP_FAIL_BIN/claude" <<'STUB'
#!/bin/sh
case "$1 $2" in "plugin install"|"plugin marketplace") exit 1 ;; esac
exit 0
STUB
chmod +x "$MCP_FAIL_BIN/claude"

check "sync-claude-mcp exits 0 when the odoo-dev plugin install fails" bash -c \
  "CLAUDE_CONFIG_DIR=\"$MCP_FAIL_CONFIG\" PATH=\"$MCP_FAIL_BIN:\$PATH\" /usr/local/bin/sync-claude-mcp 2>/dev/null"
check "sync-claude-mcp keeps the loose copies when the plugin install fails" bash -c \
  "test -f \"$MCP_FAIL_CONFIG/skills/odoo-quote/SKILL.md\""

rm -rf "$MCP_TEST_ROOT"

# --- Claude Code lifecycle hooks delivery (#327) ------------------------------
# install.sh installs the hook shim (claude-event-hook) and the settings merge
# script (sync-claude-hooks) to /usr/local/bin (outside the CLAUDE_CONFIG_DIR
# bind mount). sync-claude-hooks (feature-contributed postCreateCommand, after
# sync-claude-skills) merges the feature-owned hooks block into the live
# $CLAUDE_CONFIG_DIR/settings.json once the mount is active. Smoke assertions
# first: both scripts exist, are executable, and are syntactically valid. The
# merge itself doesn't run under `devcontainer features test` (no
# postCreateCommand there), so the behavioural checks below drive it by hand
# against a THROWAWAY config dir - never the real $CLAUDE_CONFIG_DIR.
check "claude-event-hook is installed and executable" bash -c "test -x /usr/local/bin/claude-event-hook"
check "claude-event-hook passes shell syntax check" bash -c "bash -n /usr/local/bin/claude-event-hook"
check "sync-claude-hooks is installed and executable" bash -c "test -x /usr/local/bin/sync-claude-hooks"
check "sync-claude-hooks passes shell syntax check" bash -c "bash -n /usr/local/bin/sync-claude-hooks"

# The hook shim must skip PreToolUse for the odoo MCP server's own tools (it
# logs those dispatches server-side, #326/#340) and must still log every other
# tool. This used to be `grep -q 'mcp__odoo__\*'` against the shim text, which
# passed *precisely because* the glob was the broken `mcp__odoo__*` and would
# have FAILED the moment it was corrected - rubber-stamping a guard that never
# matched a real tool name, so odoo calls were double-logged (#529/#551). The
# #529 correction to `mcp__odoo-sdk__*` was still wrong: the server key is
# `odoo-mcp`, not `odoo-sdk` (#581), so the real prefix is `mcp__odoo-mcp__*`.
#
# Assert the emitted command line instead. `odoo-sdk` is stubbed onto PATH so the
# shim resolves it and records the argv it built; no real SDK is needed. Claude
# Code namespaces MCP tools as `mcp__<server-key>__<tool>` with the key's hyphens
# preserved, and install.sh registers the key `odoo-mcp`, so
# `mcp__odoo-mcp__get_tasks` below is a production-shaped tool name.
HOOK_STUB_ROOT="$(mktemp -d)"
mkdir -p "$HOOK_STUB_ROOT/bin"
cat > "$HOOK_STUB_ROOT/bin/odoo-sdk" <<'STUB'
#!/bin/sh
# Stand-in for the real CLI: one line per invocation, recording the whole argv.
printf '%s\n' "$*" >> "$HOOK_STUB_LOG"
STUB
chmod +x "$HOOK_STUB_ROOT/bin/odoo-sdk"
export HOOK_STUB_BIN="$HOOK_STUB_ROOT/bin"
export HOOK_STUB_LOG="$HOOK_STUB_ROOT/invocations"
: > "$HOOK_STUB_LOG"

# shellcheck disable=SC2016  # single quotes defer expansion into the check subshell
check "claude-event-hook logs a normal tool but excludes mcp__odoo-mcp__* tools" bash -c '
  emit() {
    printf "{\"session_id\":\"s1\",\"tool_name\":\"%s\",\"hook_event_name\":\"PreToolUse\",\"cwd\":\"/tmp\"}" "$1" \
      | PATH="$HOOK_STUB_BIN:$PATH" /usr/local/bin/claude-event-hook PreToolUse
  }
  # An EXCLUDED tool exits before the shim forks anything, so the log is settled
  # the moment emit returns. A LOGGED tool forks a detached job, so poll for it.
  emit mcp__odoo-mcp__get_tasks
  emit Bash
  for _ in $(seq 1 50); do
    grep -q -- "--subject Bash" "$HOOK_STUB_LOG" && break
    sleep 0.2
  done
  # Bash was emitted AFTER the odoo tool, so if a regression made the shim fork
  # an odoo write too, that write was queued first - but it is detached, so give
  # it a grace period to land rather than racing the negative assertion below.
  sleep 1

  grep -q -- "--source claude:PreToolUse" "$HOOK_STUB_LOG" \
    || { echo "shim never invoked odoo-sdk for a non-odoo PreToolUse tool" >&2; exit 1; }
  grep -q -- "--subject Bash" "$HOOK_STUB_LOG" \
    || { echo "shim did not forward --subject Bash" >&2; exit 1; }
  if grep -q -- "mcp__odoo-mcp__" "$HOOK_STUB_LOG"; then
    echo "shim logged an mcp__odoo-mcp__* tool the MCP server already logs server-side" >&2
    exit 1
  fi
  # Exactly one row: proves the exclusion dropped the odoo call rather than the
  # assertions above merely failing to notice a second, differently-shaped one.
  [ "$(wc -l < "$HOOK_STUB_LOG")" -eq 1 ] \
    || { echo "expected exactly 1 odoo-sdk invocation, got $(wc -l < "$HOOK_STUB_LOG")" >&2; exit 1; }
'
rm -rf "$HOOK_STUB_ROOT"
unset HOOK_STUB_BIN HOOK_STUB_LOG

# The shim must always exit 0 and pass --attach-active-run to odoo-sdk.
check "claude-event-hook attaches the active run" bash -c \
  "grep -q -- '--attach-active-run' /usr/local/bin/claude-event-hook"

# The shim must no-op (exit 0) when odoo-sdk is absent from PATH. Run it with a
# stripped PATH (coreutils only) so `odoo-sdk` cannot be found and pipe it an
# empty payload; a nonzero exit here would block a real Claude session.
check "claude-event-hook no-ops with exit 0 when odoo-sdk is absent" bash -c \
  "printf '{}' | PATH=/usr/bin:/bin /usr/local/bin/claude-event-hook PreToolUse; test \$? -eq 0"

# #411: hook<->CLI CONTRACT, exercised end to end. The grep guards above only
# prove the flag STRINGS survive in the shim text; they cannot catch a rename on
# the SDK side. Because the shim swallows every failure (always exit 0) and forks
# the SDK call into a DETACHED background job, a rename of --attach-active-run /
# --payload or of the `claude:` source prefix would drop every event in
# production while passing all of the above. So drive the REAL claude-event-hook
# with a representative PreToolUse payload and assert a row actually LANDED,
# carrying the trimmed --payload and (proof of the whole vector) still MATCHING
# the billing predicate that keys on the `claude:` prefix. A flag/prefix drift
# fails this loudly.
#
# Self-contained by design: it provisions its OWN throwaway tracker DB with the
# SDK schema and points the shim at it via ODOO_TASK_TRACKER_DIR, so it runs
# deterministically whether or not a host-provisioned central DB is mounted (it
# is under CI's setup.sh, but NOT under a plain `devcontainer features test`) and
# never touches the real DB. Gated on the SDK being installed (absent only when
# no wheel was bundled - #674); the SDK bin dir is put on PATH so the shim's bare `odoo-sdk` resolves
# to the real installed CLI. `odoo-sdk` is deliberately NOT on the default PATH
# (only odoo-mcp/odoo-tui are symlinked), so this uses the venv bin explicitly.
# shellcheck disable=SC2016  # single quotes defer expansion into the check subshell
check "claude-event-hook drives a real PreToolUse event through --attach-active-run/--payload into a provisioned DB" bash -c '
  SDK_BIN=/usr/local/share/uv/tools/odoo-sdk/bin
  test -x "$SDK_BIN/odoo-sdk" || exit 0
  STATE="$(mktemp -d)"
  DB="$STATE/tracker.db"
  # Provision a throwaway central DB with the SDK schema (never the real one).
  "$SDK_BIN/python" -c "import sqlite3, sys; from odoo_sdk.state.db import create_schema; c = sqlite3.connect(sys.argv[1]); create_schema(c); c.commit(); c.close()" "$DB" \
    || { echo "failed to provision temp tracker DB at $DB" >&2; rm -rf "$STATE"; exit 1; }
  subj="ci-hook-e2e-$$"
  printf "{\"session_id\":\"s-%s\",\"tool_name\":\"%s\",\"hook_event_name\":\"PreToolUse\",\"cwd\":\"/tmp\"}" "$$" "$subj" \
    | ODOO_TASK_TRACKER_DIR="$STATE" PATH="$SDK_BIN:$PATH" /usr/local/bin/claude-event-hook PreToolUse
  # The shim fires the SDK write in a DETACHED background job, so poll the DB.
  for _ in $(seq 1 50); do
    "$SDK_BIN/python" - "$DB" "$subj" <<PY && { rm -rf "$STATE"; exit 0; }
import json, sqlite3, sys
from odoo_sdk.state.db import _DEVELOPMENT_SOURCE_PREDICATE
db, subj = sys.argv[1], sys.argv[2]
conn = sqlite3.connect(db)
row = conn.execute(
    f"SELECT source, payload FROM events WHERE subject = ? AND {_DEVELOPMENT_SOURCE_PREDICATE}",
    (subj,),
).fetchone()
if row is None:
    sys.exit(1)
source, payload = row
assert source == "claude:PreToolUse", source
assert json.loads(payload)["tool_name"] == subj, payload
sys.exit(0)
PY
    sleep 0.2
  done
  echo "no billing-eligible claude:PreToolUse row for subject $subj ever landed" >&2
  rm -rf "$STATE"
  exit 1
'

# Behavioural checks for sync-claude-hooks against a throwaway CLAUDE_CONFIG_DIR.
HOOKS_TEST_ROOT="$(mktemp -d)"

# (a) No settings.json → created, valid JSON, contains all feature hook entries.
HK_A="$HOOKS_TEST_ROOT/a"
mkdir -p "$HK_A"
check "sync-claude-hooks creates settings.json when absent" bash -c \
  "CLAUDE_CONFIG_DIR=\"$HK_A\" /usr/local/bin/sync-claude-hooks && test -f \"$HK_A/settings.json\""
check "created settings.json is valid JSON" bash -c "jq . \"$HK_A/settings.json\" >/dev/null"
check "settings.json contains the feature PreToolUse hook (match-all matcher)" bash -c \
  "[ \"\$(jq -r '.hooks.PreToolUse[0].matcher' \"$HK_A/settings.json\")\" = '*' ] && jq -e '.hooks.PreToolUse[] | select(.hooks[].command | contains(\"claude-event-hook PreToolUse\"))' \"$HK_A/settings.json\" >/dev/null"
check "settings.json contains all seven feature hook events" bash -c \
  "for ev in SessionStart UserPromptSubmit PreToolUse SubagentStart SubagentStop Stop SessionEnd; do jq -e --arg e \"\$ev\" '.hooks[\$e][] | select(.hooks[].command | contains(\"claude-event-hook\"))' \"$HK_A/settings.json\" >/dev/null || exit 1; done"

# (b) Running the sync TWICE yields no duplicate feature entries.
check "sync-claude-hooks is idempotent (no duplicate PreToolUse groups on re-run)" bash -c \
  "CLAUDE_CONFIG_DIR=\"$HK_A\" /usr/local/bin/sync-claude-hooks && [ \"\$(jq '[.hooks.PreToolUse[] | select(.hooks[].command | contains(\"claude-event-hook\"))] | length' \"$HK_A/settings.json\")\" = '1' ]"

# (c) A pre-seeded user setting AND a user-authored hook survive the merge.
HK_B="$HOOKS_TEST_ROOT/b"
mkdir -p "$HK_B"
cat > "$HK_B/settings.json" <<'JSON'
{ "model": "opus", "env": {"FOO": "bar"},
  "hooks": {
    "PreToolUse": [ {"matcher": "Bash", "hooks": [{"type":"command","command":"/home/me/my-own-hook.sh"}]} ]
  } }
JSON
check "sync-claude-hooks merges into a user-populated settings.json" bash -c \
  "CLAUDE_CONFIG_DIR=\"$HK_B\" /usr/local/bin/sync-claude-hooks"
check "a pre-seeded user setting survives the merge" bash -c \
  "[ \"\$(jq -r '.model' \"$HK_B/settings.json\")\" = 'opus' ] && [ \"\$(jq -r '.env.FOO' \"$HK_B/settings.json\")\" = 'bar' ]"
check "a user-authored hook survives the merge" bash -c \
  "jq -e '.hooks.PreToolUse[] | select(.hooks[].command == \"/home/me/my-own-hook.sh\")' \"$HK_B/settings.json\" >/dev/null"
check "the feature hook is added alongside the user's (two PreToolUse groups)" bash -c \
  "[ \"\$(jq '.hooks.PreToolUse | length' \"$HK_B/settings.json\")\" = '2' ]"

# (d) A corrupt/unparseable settings.json is left strictly alone (never destroy
# the user's real config).
HK_C="$HOOKS_TEST_ROOT/c"
mkdir -p "$HK_C"
printf '{ this is : not json ' > "$HK_C/settings.json"
check "sync-claude-hooks leaves a corrupt settings.json untouched and exits 0" bash -c \
  "before=\$(cat \"$HK_C/settings.json\"); CLAUDE_CONFIG_DIR=\"$HK_C\" /usr/local/bin/sync-claude-hooks; rc=\$?; [ \$rc -eq 0 ] && [ \"\$before\" = \"\$(cat \"$HK_C/settings.json\")\" ]"

rm -rf "$HOOKS_TEST_ROOT"

# --- mempalace palace root symlink (#596, #643) -------------------------------
# Upstream mempalace's hooks CLI hardcodes ~/.mempalace as its palace root and
# treats its absence as the user-removed kill-switch, while the MCP server uses
# the bind mount at /usr/local/share/mempalace - so without this link every
# plugin hook fire silently no-oped. install.sh symlinks the home path onto the
# mount so both sides agree on one root.
# shellcheck disable=SC2088  # literal ~ in a human-readable test description, not a path to expand
check "~/.mempalace is a symlink" bash -c "test -L \"\$HOME/.mempalace\""
# shellcheck disable=SC2088  # literal ~ in a human-readable test description, not a path to expand
check "~/.mempalace points at the bind-mounted palace root" bash -c \
  "[ \"\$(readlink \"\$HOME/.mempalace\")\" = '/usr/local/share/mempalace' ]"

# The env var the whole arrangement is keyed on. Nothing asserted this before,
# so a typo in devcontainer-feature.json's containerEnv would have gone unnoticed
# until mempalace quietly wrote to its upstream default instead (#643).
check "MEMPALACE_PALACE_PATH points into the bind-mounted palace root" bash -c \
  "[ \"\$MEMPALACE_PALACE_PATH\" = '/usr/local/share/mempalace/palace' ]"

# #643 regression path: the original guard only created the link when the path
# was ABSENT, so a build that found a real directory there warned and gave up -
# and everything mempalace then wrote under it lived outside the mount and was
# discarded on the next rebuild. mempalace-repair must migrate such a
# directory onto the mount and replace it with the link. MEMPALACE_MOUNT points
# the repair at a sandbox so the real palace is never touched.
check "mempalace-repair is on PATH and executable" bash -c \
  "test -x /usr/local/bin/mempalace-repair"

check "mempalace-repair creates the link when the path is absent" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && [ \"\$(readlink \"\$d/home/.mempalace\")\" = \"\$d/mount\" ]"

check "mempalace-repair replaces a real directory with the link (#643)" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home/.mempalace/hook_state\" \"\$d/mount\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && test -L \"\$d/home/.mempalace\" && [ \"\$(readlink \"\$d/home/.mempalace\")\" = \"\$d/mount\" ]"

check "mempalace-repair migrates the directory's contents onto the mount" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home/.mempalace/wal\" \"\$d/mount\"; printf 'stranded\n' > \"\$d/home/.mempalace/wal/entry.jsonl\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && [ \"\$(cat \"\$d/mount/wal/entry.jsonl\")\" = 'stranded' ]"

# The mount is the surviving root, so its copy of a colliding file wins.
check "mempalace-repair does not clobber files already on the mount" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home/.mempalace\" \"\$d/mount\"; printf 'local\n' > \"\$d/home/.mempalace/config.json\"; printf 'mounted\n' > \"\$d/mount/config.json\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && [ \"\$(cat \"\$d/mount/config.json\")\" = 'mounted' ]"

# A regular file there is a user artifact and must survive untouched.
check "mempalace-repair leaves a regular file at the path untouched" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; printf 'mine\n' > \"\$d/home/.mempalace\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && [ \"\$(cat \"\$d/home/.mempalace\")\" = 'mine' ] && ! test -L \"\$d/home/.mempalace\""

check "mempalace-repair is idempotent over an already correct link" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && [ \"\$(readlink \"\$d/home/.mempalace\")\" = \"\$d/mount\" ]"

# The stray `~` artifact (#643): mempalace's MCP server abspath()s a literal
# `~/...` --palace without expanduser(), so a real directory named `~` can appear
# at the palace root, stranding memories where nothing will ever read them.
# mempalace-repair removes exactly that shape and nothing else.
check "no stray '~' directory at the palace root" bash -c \
  "! test -e '/usr/local/share/mempalace/~'"
check "mempalace-repair removes a stray '~' directory at the mount root" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount/~/.mempalace/palace\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && ! test -e \"\$d/mount/~\""
# Narrowly matched: real palace data next to it must survive.
check "mempalace-repair leaves the rest of the mount alone" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount/~\" \"\$d/mount/palace\"; printf 'keep\n' > \"\$d/mount/hallways.json\"; MEMPALACE_MOUNT=\"\$d/mount\" /usr/local/bin/mempalace-repair \"\$d/home\" && test -d \"\$d/mount/palace\" && [ \"\$(cat \"\$d/mount/hallways.json\")\" = 'keep' ]"

# palace_path reconciliation (#643): Config.palace_path returns on the env
# branch before consulting config.json and never reports the disagreement, so a
# config.json carried in on the mount can name a host path that does not exist
# here. mempalace-repair rewrites ONLY that key.
check "mempalace-repair rewrites a disagreeing palace_path" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; printf '{\"palace_path\": \"/home/someone-else/.mempalace/palace\"}' > \"\$d/mount/config.json\"; MEMPALACE_MOUNT=\"\$d/mount\" MEMPALACE_PALACE_PATH=\"\$d/mount/palace\" /usr/local/bin/mempalace-repair \"\$d/home\" && python3 -c \"import json,sys;print(json.load(open(sys.argv[1]))['palace_path'])\" \"\$d/mount/config.json\" | grep -qx \"\$d/mount/palace\""
# topic_wings / hall_keywords are user content and must survive verbatim.
check "mempalace-repair preserves other config.json keys" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; printf '{\"palace_path\": \"/nope\", \"topic_wings\": [\"emotions\"], \"hall_keywords\": {\"emotions\": [\"scared\"]}}' > \"\$d/mount/config.json\"; MEMPALACE_MOUNT=\"\$d/mount\" MEMPALACE_PALACE_PATH=\"\$d/mount/palace\" /usr/local/bin/mempalace-repair \"\$d/home\" && python3 -c \"import json,sys;c=json.load(open(sys.argv[1]));assert c['topic_wings']==['emotions'];assert c['hall_keywords']=={'emotions':['scared']}\" \"\$d/mount/config.json\""
# A config that already agrees must be left byte-identical.
check "mempalace-repair is a no-op on an agreeing config.json" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; printf '{\"palace_path\":\"PLACEHOLDER\"}' | sed \"s|PLACEHOLDER|\$d/mount/palace|\" > \"\$d/mount/config.json\"; before=\"\$(cat \"\$d/mount/config.json\")\"; MEMPALACE_MOUNT=\"\$d/mount\" MEMPALACE_PALACE_PATH=\"\$d/mount/palace\" /usr/local/bin/mempalace-repair \"\$d/home\" && [ \"\$before\" = \"\$(cat \"\$d/mount/config.json\")\" ]"
# A corrupt config.json must never abort the repair or be destroyed.
check "mempalace-repair leaves a corrupt config.json untouched and exits 0" bash -c \
  "d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\"; printf '{ not json ' > \"\$d/mount/config.json\"; MEMPALACE_MOUNT=\"\$d/mount\" MEMPALACE_PALACE_PATH=\"\$d/mount/palace\" /usr/local/bin/mempalace-repair \"\$d/home\" 2>/dev/null; rc=\$?; [ \$rc -eq 0 ] && [ \"\$(cat \"\$d/mount/config.json\")\" = '{ not json ' ]"

# --- mempalace-as-only-memory asserts (#744) ----------------------------------
# Native Claude auto-memory is off in the shared settings.json and the native
# memory files were mined into the palace, so mempalace is the only memory left
# and three things have to hold: hooks.auto_save true, identity.txt present, and
# an executable SessionStart recall hook. The repair step REPORTS on all three
# and repairs none of them - except a wholly absent identity.txt, which it seeds.
# Driven against the same MEMPALACE_MOUNT sandbox as the checks above, plus a
# sandbox CLAUDE_CONFIG_DIR so the real claude-home is never read.

# The sandbox every assert case below starts from: a home, a mount, a fake
# claude-home, and a config.json whose palace_path already agrees (so step 3
# stays quiet and only the step-4 output is under test).
_ASSERT_SETUP="d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/mount\" \"\$d/claude/hooks\"; printf '{\"palace_path\":\"PLACEHOLDER\",\"hooks\":{\"auto_save\":true}}' | sed \"s|PLACEHOLDER|\$d/mount/palace|\" > \"\$d/mount/config.json\"; _run() { MEMPALACE_MOUNT=\"\$d/mount\" CLAUDE_CONFIG_DIR=\"\$d/claude\" MEMPALACE_PALACE_PATH=\"\$d/mount/palace\" /usr/local/bin/mempalace-repair \"\$d/home\"; };"

# A true hooks.auto_save with everything else in place is the healthy container:
# the assert step must say nothing at all on stderr.
check "mempalace-repair is silent when auto_save, identity and recall hook are all good" bash -c \
  "$_ASSERT_SETUP printf 'agent: devcontainer-claude\n' > \"\$d/mount/identity.txt\"; printf '#!/bin/sh\n' > \"\$d/claude/hooks/mempalace-recall.sh\"; chmod +x \"\$d/claude/hooks/mempalace-recall.sh\"; err=\"\$(_run 2>&1 >/dev/null)\"; [ -z \"\$err\" ]"

# The #744 bug itself: auto_save was false, so every Stop/SessionEnd/PreCompact
# hook fire saved nothing and nothing said so.
check "mempalace-repair warns when hooks.auto_save is false" bash -c \
  "$_ASSERT_SETUP printf '{\"palace_path\":\"PLACEHOLDER\",\"hooks\":{\"auto_save\":false}}' | sed \"s|PLACEHOLDER|\$d/mount/palace|\" > \"\$d/mount/config.json\"; _run 2>&1 >/dev/null | grep -q 'auto_save'"

# Absent key, not false: same inert hooks, so the same warning is owed.
check "mempalace-repair warns when hooks.auto_save is absent" bash -c \
  "$_ASSERT_SETUP printf '{\"palace_path\":\"PLACEHOLDER\"}' | sed \"s|PLACEHOLDER|\$d/mount/palace|\" > \"\$d/mount/config.json\"; _run 2>&1 >/dev/null | grep -q 'auto_save'"

# Reporting only: a false value is the user's file to fix, and rewriting it here
# would hide whatever turned it off.
check "mempalace-repair never rewrites config.json to fix auto_save" bash -c \
  "$_ASSERT_SETUP printf '{\"palace_path\":\"PLACEHOLDER\",\"hooks\":{\"auto_save\":false}}' | sed \"s|PLACEHOLDER|\$d/mount/palace|\" > \"\$d/mount/config.json\"; before=\"\$(cat \"\$d/mount/config.json\")\"; _run >/dev/null 2>&1 && [ \"\$before\" = \"\$(cat \"\$d/mount/config.json\")\" ]"

# identity.txt is L0 for `mempalace wake-up`. Absent means there is no user
# content to preserve, so this is the one item the step is allowed to create.
check "mempalace-repair seeds identity.txt when it is absent (#744)" bash -c \
  "$_ASSERT_SETUP _run >/dev/null 2>&1 && test -f \"\$d/mount/identity.txt\" && grep -q 'devcontainer-claude' \"\$d/mount/identity.txt\""

check "mempalace-repair logs that it seeded identity.txt" bash -c \
  "$_ASSERT_SETUP _run 2>/dev/null | grep -q 'seeded.*identity.txt'"

# An existing one is the user's own text, however stale it looks: byte-identical
# afterwards, and no second seeding on the next run.
check "mempalace-repair leaves an existing identity.txt byte-identical" bash -c \
  "$_ASSERT_SETUP printf 'agent: someone-else\nrole: hand written\n' > \"\$d/mount/identity.txt\"; before=\"\$(cat \"\$d/mount/identity.txt\")\"; _run >/dev/null 2>&1 && [ \"\$before\" = \"\$(cat \"\$d/mount/identity.txt\")\" ] && ! grep -q 'devcontainer-claude' \"\$d/mount/identity.txt\""

check "mempalace-repair does not re-seed identity.txt on a second run" bash -c \
  "$_ASSERT_SETUP _run >/dev/null 2>&1; before=\"\$(cat \"\$d/mount/identity.txt\")\"; _run >/dev/null 2>&1 && [ \"\$before\" = \"\$(cat \"\$d/mount/identity.txt\")\" ]"

# The recall hook is hand-maintained and named by path from settings.json, so a
# missing or non-executable file fails the hook on every session start. Warn -
# and never create it, since a stub would recall nothing while looking healthy.
check "mempalace-repair warns when the recall hook is missing" bash -c \
  "$_ASSERT_SETUP _run 2>&1 >/dev/null | grep -q 'mempalace-recall.sh'"

check "mempalace-repair never creates the recall hook" bash -c \
  "$_ASSERT_SETUP _run >/dev/null 2>&1; ! test -e \"\$d/claude/hooks/mempalace-recall.sh\""

check "mempalace-repair warns when the recall hook is not executable" bash -c \
  "$_ASSERT_SETUP printf '#!/bin/sh\n' > \"\$d/claude/hooks/mempalace-recall.sh\"; chmod 0644 \"\$d/claude/hooks/mempalace-recall.sh\"; _run 2>&1 >/dev/null | grep -q 'not executable'"

# Every branch above is advisory: none of them may change the exit status.
check "mempalace-repair still exits 0 with all three asserts failing" bash -c \
  "$_ASSERT_SETUP printf '{\"palace_path\":\"PLACEHOLDER\",\"hooks\":{\"auto_save\":false}}' | sed \"s|PLACEHOLDER|\$d/mount/palace|\" > \"\$d/mount/config.json\"; _run >/dev/null 2>&1; [ \$? -eq 0 ]"

# --- mempalace workspace init, run-once (#643 follow-up) ----------------------
# `mempalace init` writes the rooms list the miner routes files by; without it
# everything lands in a single `general` room. It is wired into
# postCreateCommand, which `devcontainer features test` does not run, so the
# guards are driven by hand here. MEMPALACE_INIT_CMD substitutes a stub for the
# real binary so these assert the run-once policy, not mempalace's detector.
check "mempalace-init-workspace is on PATH and executable" bash -c \
  "test -x /usr/local/bin/mempalace-init-workspace"

# A stub that records that it was invoked, and with what.
_INIT_STUB_SETUP="d=\"\$(mktemp -d)\"; mkdir -p \"\$d/bin\" \"\$d/repo\"; printf '#!/bin/sh\nprintf \"%%s\\\\n\" \"\$*\" >> \"\$0.calls\"\n' > \"\$d/bin/stub\"; chmod +x \"\$d/bin/stub\";"

# The whole point: an existing mempalace.yaml is the user's curated file and
# init must never be re-run over it (init overwrites rather than merges).
check "mempalace-init-workspace never re-runs over an existing mempalace.yaml" bash -c \
  "$_INIT_STUB_SETUP printf 'wing: mine\n' > \"\$d/repo/mempalace.yaml\"; MEMPALACE_INIT_CMD=\"\$d/bin/stub\" PATH=\"\$d/bin:\$PATH\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" && ! test -e \"\$d/bin/stub.calls\" && [ \"\$(cat \"\$d/repo/mempalace.yaml\")\" = 'wing: mine' ]"

check "mempalace-init-workspace runs init when mempalace.yaml is absent" bash -c \
  "$_INIT_STUB_SETUP MEMPALACE_INIT_CMD=\"\$d/bin/stub\" PATH=\"\$d/bin:\$PATH\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" && grep -q 'init' \"\$d/bin/stub.calls\""

# Non-interactive and offline, or it hangs//errors in postCreateCommand.
check "mempalace-init-workspace passes --yes and --no-llm" bash -c \
  "$_INIT_STUB_SETUP MEMPALACE_INIT_CMD=\"\$d/bin/stub\" PATH=\"\$d/bin:\$PATH\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" && grep -q -- '--yes' \"\$d/bin/stub.calls\" && grep -q -- '--no-llm' \"\$d/bin/stub.calls\""

# --auto-mine would double-mine: the plugin hooks already drive mining.
check "mempalace-init-workspace does not pass --auto-mine" bash -c \
  "$_INIT_STUB_SETUP MEMPALACE_INIT_CMD=\"\$d/bin/stub\" PATH=\"\$d/bin:\$PATH\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" && ! grep -q -- '--auto-mine' \"\$d/bin/stub.calls\""

check "MEMPALACE_SKIP_INIT opts out entirely" bash -c \
  "$_INIT_STUB_SETUP MEMPALACE_SKIP_INIT=1 MEMPALACE_INIT_CMD=\"\$d/bin/stub\" PATH=\"\$d/bin:\$PATH\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" && ! test -e \"\$d/bin/stub.calls\""

# Never block container creation: a missing mine root, a missing binary and a
# failing init are all warnings, because mining still works via the `general`
# fallback. (An unresolvable MEMPAL_DIR means mining NOTHING, and that is
# resolve-mempal-dir's job to fail loudly on - see #485.)
check "mempalace-init-workspace exits 0 when the mine root does not exist" bash -c \
  "$_INIT_STUB_SETUP MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace \"\$d/nonexistent\" 2>/dev/null"
check "mempalace-init-workspace exits 0 when mempalace is not on PATH" bash -c \
  "$_INIT_STUB_SETUP MEMPALACE_INIT_CMD=definitely-not-a-real-binary /usr/local/bin/mempalace-init-workspace \"\$d/repo\" 2>/dev/null && ! test -e \"\$d/repo/mempalace.yaml\""
check "mempalace-init-workspace exits 0 when init itself fails" bash -c \
  "$_INIT_STUB_SETUP printf '#!/bin/sh\nexit 1\n' > \"\$d/bin/stub\"; chmod +x \"\$d/bin/stub\"; MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" 2>/dev/null"

# With no argument it falls back to the MEMPAL_DIR resolve-mempal-dir persisted.
check "mempalace-init-workspace falls back to the persisted MEMPAL_DIR" bash -c \
  "$_INIT_STUB_SETUP printf 'wing: already\n' > \"\$d/repo/mempalace.yaml\"; MEMPAL_DIR=\"\$d/repo\" MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace | grep -q 'already exists'"

# Headless contract (upstream issue #179; verified against MemPalace 3.7.1).
# --yes covers the entity + room prompts, --no-llm the provider consent gate,
# and an EOF stdin the post-init mine prompt that --yes deliberately does NOT
# cover. A `yes` pipe is the wrong tool here: it answers Y to that mine prompt
# (a full synchronous mine inside postCreateCommand) and never closes, so any
# prompt escaping --yes loops forever.
check "mempalace-init-workspace feeds init an EOF stdin, not a yes-pipe" bash -c \
  "$_INIT_STUB_SETUP printf '#!/bin/sh\nhead -c 1 > \"\$0.stdin\"\n' > \"\$d/bin/stub\"; chmod +x \"\$d/bin/stub\"; MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" >/dev/null 2>&1; test ! -s \"\$d/bin/stub.stdin\""
# A wedged init must degrade to a warning, never hang container creation.
check "mempalace-init-workspace kills an init that exceeds its timeout" bash -c \
  "$_INIT_STUB_SETUP printf '#!/bin/sh\nsleep 30\n' > \"\$d/bin/stub\"; chmod +x \"\$d/bin/stub\"; s=\$(date +%s); MEMPALACE_INIT_CMD=\"\$d/bin/stub\" MEMPALACE_INIT_TIMEOUT=2 /usr/local/bin/mempalace-init-workspace \"\$d/repo\" 2>&1 | grep -q 'exceeded 2s'; rc=\$?; e=\$((\$(date +%s)-s)); [ \$rc -eq 0 ] && [ \$e -lt 20 ]"

# init appends its own block to <repo>/.gitignore (upstream #185). The same two
# names are already ignored machine-wide by core.excludesfile (#643), so that
# append is redundant AND leaves an uncommitted diff in the user's workspace.
_GI_STUB="printf '#!/bin/sh\nprintf \"\\\\n# MemPalace per-project files (issue #185)\\\\nmempalace.yaml\\\\nentities.json\\\\n\" >> \"\$2/.gitignore\"\n' > \"\$d/bin/stub\"; chmod +x \"\$d/bin/stub\";"
check "mempalace-init-workspace reverts init's append to an existing .gitignore" bash -c \
  "$_INIT_STUB_SETUP $_GI_STUB printf 'node_modules/\n*.log\n' > \"\$d/repo/.gitignore\"; MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" >/dev/null 2>&1; [ \"\$(cat \"\$d/repo/.gitignore\")\" = \"\$(printf 'node_modules/\n*.log')\" ]"
check "mempalace-init-workspace removes a .gitignore that init created" bash -c \
  "$_INIT_STUB_SETUP $_GI_STUB MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" >/dev/null 2>&1; ! test -e \"\$d/repo/.gitignore\""
# ...but never destroys one carrying real user content.
check "mempalace-init-workspace keeps a .gitignore with unexpected content" bash -c \
  "$_INIT_STUB_SETUP printf '#!/bin/sh\nprintf \"secrets.env\\\\n\" >> \"\$2/.gitignore\"\n' > \"\$d/bin/stub\"; chmod +x \"\$d/bin/stub\"; MEMPALACE_INIT_CMD=\"\$d/bin/stub\" /usr/local/bin/mempalace-init-workspace \"\$d/repo\" >/dev/null 2>&1; grep -q 'secrets.env' \"\$d/repo/.gitignore\""

# End-to-end against the REAL binary: init must complete headless, with an
# isolated HOME so the container's own palace is untouched. Bounded so a
# regression here fails the suite instead of wedging it.
check "real mempalace init completes headless and writes rooms" bash -c \
  "! command -v mempalace >/dev/null 2>&1 || { d=\"\$(mktemp -d)\"; mkdir -p \"\$d/home\" \"\$d/repo/src\" \"\$d/repo/docs\"; echo x > \"\$d/repo/src/a.py\"; echo y > \"\$d/repo/docs/b.md\"; (cd \"\$d/repo\" && git init -q .); HOME=\"\$d/home\" MEMPALACE_PALACE_PATH=\"\$d/home/palace\" MEMPALACE_INIT_TIMEOUT=120 /usr/local/bin/mempalace-init-workspace \"\$d/repo\" >/dev/null 2>&1 && test -f \"\$d/repo/mempalace.yaml\" && ! test -e \"\$d/repo/.gitignore\"; }"

# Regression guard for #233: the credential-holding config dirs must be 0700,
# not the umask default 0755, or real secrets (e.g. ~/.claude/.credentials.json,
# gh's hosts.yml) live in a world-readable dir. The mode comes from
# persisted-paths.tsv's `mode` column and is enforced by BOTH consumers that
# create these dirs: install.sh chmods the container-side targets, and setup.sh
# chmods the host-side sources. Both matter, and these assertions cover
# whichever is visible: CI runs `sh ./setup.sh` before this test, so the
# feature's bind mounts ARE active here and stat sees the HOST dirs' modes
# through the mount; in a mountless run (e.g. `devcontainer features test`
# without the host dirs) stat sees install.sh's chmod instead. Same manifest
# column either way, so the expected values are identical.
# pr-automation holds no credentials and deliberately stays 0755. shell-history
# is 0777 (world-writable): its host dir is bind-mounted over the container dir,
# so a container user whose uid differs from the host owner could not otherwise
# create/append bash_history and every command printed a "cannot create:
# Permission denied" error (#323); world-writable lets any uid write it.
# NOTE: stat -c '%a' prints octal WITHOUT a leading zero (700 / 755 / 777).
check "claude-home is chmod 0700 (credentials not world-readable)" bash -c \
  "[ \"\$(stat -c '%a' /usr/local/share/claude-home)\" = '700' ]"
check "gh-cli-config is chmod 0700 (credentials not world-readable)" bash -c \
  "[ \"\$(stat -c '%a' /usr/local/share/gh-cli-config)\" = '700' ]"
check "odoo-sdk-config is chmod 0700 (credentials not world-readable)" bash -c \
  "[ \"\$(stat -c '%a' /usr/local/share/odoo-sdk-config)\" = '700' ]"
check "coderabbit-config is chmod 0700 (credentials not world-readable)" bash -c \
  "[ \"\$(stat -c '%a' /usr/local/share/coderabbit-config)\" = '700' ]"
check "coderabbit CLI home dir is chmod 0700 (auth.json not world-readable, #661)" bash -c \
  "[ \"\$(stat -c '%a' /home/vscode/.coderabbit)\" = '700' ]"
check "pr-automation dir stays 0755 (holds no credentials)" bash -c \
  "[ \"\$(stat -c '%a' /usr/local/share/pr-automation)\" = '755' ]"
check "shell-history dir is 0777 (any uid can create/append bash_history, #323)" bash -c \
  "[ \"\$(stat -c '%a' /usr/local/share/shell-history)\" = '777' ]"

reportResults
